<?php /* BISM4RCK-KUN3H0 2026 */ include app_path('views/layouts/header.php'); ?><div class="container-fluid"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2>Account Management</h2><div class="text-muted">Create, review, and remove resident, guard, and admin accounts. Vehicles and blacklist live on separate pages.</div></div></div><div class="row g-3"><div class="col-xl-5"><div class="gh-card p-4"><h5>Add Account</h5><form method="post" class="d-grid gap-2"><?=csrf_field()?><input type="hidden" name="action" value="create_user"><input class="form-control" name="full_name" placeholder="Full name" required><input class="form-control" type="email" name="email" placeholder="Email" required><input class="form-control" type="password" name="password" placeholder="Password (6+ chars)" minlength="6" required><select class="form-select" id="accountRole" name="role" required><option value="">Account type...</option><option value="resident">Resident</option><option value="guard">Guard</option><option value="admin">Admin</option></select><div id="residentFields" class="d-none border rounded-3 p-3 bg-light"><strong>Resident Address</strong><div class="row g-2 mt-1"><div class="col"><label>Block</label><input class="form-control" id="resident_block" name="resident_block" inputmode="numeric"></div><div class="col"><label>Lot</label><input class="form-control" id="resident_lot" name="resident_lot" inputmode="numeric"></div><div class="col"><label>Letter</label><input class="form-control text-uppercase" id="resident_letter" name="resident_letter" maxlength="1"></div></div><div class="small text-muted mt-2">Stored house number: <strong id="resident-house-preview">Block-Lot-Letter</strong></div><input class="form-control mt-2" name="contact_number" placeholder="Contact number"></div><div id="guardFields" class="d-none border rounded-3 p-3 bg-light"><strong>Guard Details</strong><input class="form-control mt-2" name="guard_code" placeholder="Guard ID"><input class="form-control mt-2" name="shift_name" placeholder="Shift"><input class="form-control mt-2" name="contact_number_guard" placeholder="Contact number"></div><div id="adminFields" class="d-none border rounded-3 p-3 bg-light"><strong>Admin Details</strong><input class="form-control mt-2" name="admin_code" placeholder="Admin ID"></div><button class="btn gh-primary rounded-pill">Create Account</button></form></div></div><div class="col-xl-7"><div class="gh-card p-4"><h5>Accounts</h5><div class="table-responsive"><table class="table gh-table align-middle"><thead><tr><th>Name</th><th>Role</th><th>Email</th><th>House / Details</th><th></th></tr></thead><tbody><?php foreach($residents as $r): ?><tr><td><?=e($r['full_name'])?></td><td>Resident</td><td><?=e($r['email'])?></td><td><?=e($r['house_number'])?></td><td><form method="post" onsubmit="return confirm('Remove this resident and their vehicles?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_user"><input type="hidden" name="user_id" value="<?=e($r['user_id'])?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form></td></tr><?php endforeach;?><?php foreach(array_merge($guards,$admins) as $u): ?><tr><td><?=e($u['full_name'])?></td><td><?=e(ucfirst($u['role']))?></td><td><?=e($u['email'])?></td><td><?=e(ucfirst($u['role']))?> account</td><td><?php if((int)$u['id']!==(int)current_user()['id']): ?><form method="post" onsubmit="return confirm('Remove this account?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_user"><input type="hidden" name="user_id" value="<?=e($u['id'])?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form><?php else:?><span class="small text-muted">Current account</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const role=document.getElementById('accountRole'),boxes={resident:document.getElementById('residentFields'),guard:document.getElementById('guardFields'),admin:document.getElementById('adminFields')},b=document.getElementById('resident_block'),l=document.getElementById('resident_lot'),x=document.getElementById('resident_letter'),p=document.getElementById('resident-house-preview');function update(){Object.keys(boxes).forEach(k=>boxes[k].classList.toggle('d-none',role.value!==k));const B=b.value.trim(),L=l.value.trim(),X=x.value.trim().toUpperCase();p.textContent=B&&L?B+'-'+L+(X?'-'+X:''):'Block-Lot-Letter';}role.addEventListener('change',update);[b,l,x].forEach(el=>el.addEventListener('input',update));update();});</script><?php include app_path('views/layouts/footer.php'); ?>
